import XCTest

@testable import Web5

class VP1BVerifierTests: XCTestCase {

    func testVerifyQrCodeText_ValidQRCode() async throws {
        let validQRCodeText = "VP1-"

        let vp1b = try VP1BVerifier.verifyQRCode(qrcode: validQRCodeText)

        if let jsonData = try? JSONSerialization.data(withJSONObject: vp1b.expanded(), options: .prettyPrinted),
           let jsonString = String(data: jsonData, encoding: .utf8) {
            print(jsonString)
        }

        XCTAssertNotNil(vp1b.credential, "The credential should not be nil.")
    }
}
